/* Electricity Prices · Europe — dark interactive map
 * Data: data/data.json (generated by fetch_data.py from api.energy-charts.info)
 * To point at a live backend instead, serve the same JSON shape from an API
 * and change DATA_URL below.
 */
const DATA_URL = "data/data.json";
const GEO_URL = "geo/zones.geojson";
const DE_GEO_URL = "geo/de_states.geojson";

const state = { data: null, tIdx: 0, playing: false, selected: null, layers: {} };
const $ = (id) => document.getElementById(id);

/* ---------- price color scale (diverging, pivot at 0 €/MWh) ---------- */
let domainLo = -10, domainHi = 100;
const STOP_LOW = [[0, "#0b7a75"], [0.5, "#2aa881"], [1, "#4cc38a"]];
const STOP_HIGH = [[0, "#8fce5e"], [0.35, "#f2d23c"], [0.65, "#f08a3c"], [0.85, "#e5484d"], [1, "#9b4dca"]];

function lerp(a, b, t) { return a + (b - a) * t; }
function hexLerp(c1, c2, t) {
  const p = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
  const [a, b] = [p(c1), p(c2)];
  return `rgb(${Math.round(lerp(a[0], b[0], t))},${Math.round(lerp(a[1], b[1], t))},${Math.round(lerp(a[2], b[2], t))})`;
}
function ramp(stops, t) {
  t = Math.max(0, Math.min(1, t));
  for (let i = 1; i < stops.length; i++) {
    if (t <= stops[i][0]) {
      const [t0, c0] = stops[i - 1], [t1, c1] = stops[i];
      return hexLerp(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return stops[stops.length - 1][1];
}
function priceColor(v) {
  if (v == null) return "#232b35";
  if (v <= 0) {
    const t = domainLo < 0 ? Math.max(0, (v - domainLo) / (0 - domainLo)) : 1;
    return ramp(STOP_LOW, 1 - t);
  }
  const t = domainHi > 0 ? Math.min(1, v / domainHi) : 0;
  return ramp(STOP_HIGH, t);
}

/* ---------- formatting ---------- */
const fmtDT = new Intl.DateTimeFormat("en-GB", {
  weekday: "short", day: "numeric", month: "short",
  hour: "2-digit", minute: "2-digit", timeZone: "Europe/Berlin",
});
const fmtD = new Intl.DateTimeFormat("en-GB", {
  day: "numeric", month: "short", timeZone: "Europe/Berlin",
});
const fmtT = new Intl.DateTimeFormat("en-GB", {
  hour: "2-digit", minute: "2-digit", timeZone: "Europe/Berlin",
});
const fmtPrice = (v) => v == null ? "no data" : v.toFixed(2);

function zoneAt(emName) { return state.data.zones[emName]; }
function priceAt(emName, i) {
  const z = zoneAt(emName);
  return z && z.price ? z.price[i] : null;
}

/* ---------- map ---------- */
let map, geoLayer;

function styleFeature(f) {
  const v = priceAt(f.properties.zoneName, state.tIdx);
  return {
    fillColor: priceColor(v),
    fillOpacity: v == null ? 0.55 : 0.85,
    color: "rgba(255,255,255,0.28)",
    weight: 1,
  };
}

function initMap(geo) {
  map = L.map("map", {
    zoomControl: false, attributionControl: true,
    minZoom: 3, maxZoom: 9, zoomSnap: 0.5, worldCopyJump: false,
  });
  L.control.zoom({ position: "bottomleft" }).addTo(map);
  L.tileLayer("https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}", {
    maxZoom: 12,
    attribution: "Tiles © Esri · data: energy-charts.info (Fraunhofer ISE, CC BY 4.0)",
  }).addTo(map);

  geoLayer = L.geoJSON(geo, {
    style: styleFeature,
    onEachFeature: (f, layer) => {
      const name = f.properties.zoneName;
      state.layers[name] = layer;
      layer.on({
        mouseover: (e) => {
          layer.setStyle({ weight: 2, color: "rgba(255,255,255,0.85)" });
          layer.bringToFront();
          showTip(e.originalEvent, name);
        },
        mousemove: (e) => showTip(e.originalEvent, name),
        mouseout: () => {
          geoLayer.resetStyle(layer);
          layer.setStyle(styleFeature(f));
          $("tooltip").classList.add("hidden");
        },
        click: () => selectZone(name),
      });
    },
  }).addTo(map);
  map.fitBounds(geoLayer.getBounds().pad(0.05));
}

function showTip(ev, name) {
  const z = zoneAt(name);
  const v = priceAt(name, state.tIdx);
  const tip = $("tooltip");
  tip.innerHTML = `<b>${z ? z.label : name}</b> · <span class="tt-price">${fmtPrice(v)} €/MWh</span>`;
  tip.style.left = ev.clientX + "px";
  tip.style.top = ev.clientY + "px";
  tip.classList.remove("hidden");
}

function restyle() {
  if (!geoLayer) return;
  geoLayer.eachLayer((l) => l.setStyle(styleFeature(l.feature)));
  restyleDeStates();
  updateTimeUI();
  if (state.selected) renderPanel(state.selected);
}

/* ---------- legend ---------- */
function buildLegend() {
  const lo = domainLo, hi = domainHi;
  const stops = [];
  for (let i = 0; i <= 20; i++) {
    const v = lo + (hi - lo) * (i / 20);
    stops.push(`${priceColor(v)} ${i * 5}%`);
  }
  $("legend-bar").style.background = `linear-gradient(90deg, ${stops.join(",")})`;
  $("lg-min").textContent = Math.round(lo);
  $("lg-mid").textContent = "0";
  $("lg-max").textContent = Math.round(hi);
}

/* ---------- panel ---------- */
const MIX_COLORS = {
  "Nuclear": "#e5ae10", "Solar": "#ffc94d", "Wind onshore": "#66c2a5",
  "Wind offshore": "#3288bd", "Hydro Run-of-River": "#4a80b4",
  "Hydro water reservoir": "#2f5f8a", "Hydro pumped storage": "#7a9cc6",
  "Fossil gas": "#e05d4f", "Fossil hard coal": "#6b4f3f",
  "Fossil brown coal / lignite": "#8a6a4f", "Fossil oil": "#8c564b",
  "Fossil coal-derived gas": "#9c6b5e", "Biomass": "#3f9e4d",
  "Waste": "#a0a0a0", "Geothermal": "#d95f02", "Others": "#5a6675",
};
const mixColor = (n) => MIX_COLORS[n] || "#5a6675";

function nearestIdx(ts, t) {
  if (!ts || !ts.length) return -1;
  let best = 0, bd = Infinity;
  for (let i = 0; i < ts.length; i++) {
    const d = Math.abs(ts[i] - t);
    if (d < bd) { bd = d; best = i; }
  }
  return bd <= 3600 ? best : -1;
}

function selectZone(name) {
  state.selected = name;
  if (name === "DE") showDeOverlay(); else hideDeOverlay();
  $("panel").classList.remove("hidden");
  renderPanel(name);
  if (window.innerWidth < 900) $("panel").scrollTop = 0;
}

function renderPanel(name) {
  const z = zoneAt(name);
  const t = state.data.timeline[state.tIdx];
  const v = z.price ? z.price[state.tIdx] : null;

  $("p-name").textContent = z.label;
  $("p-sub").textContent = z.bzn ? `Bidding zone ${z.bzn}` : "No market data";
  $("p-price").textContent = v == null ? "–" : v.toFixed(2);
  $("p-price").style.color = v == null ? "var(--muted)" : priceColor(v);
  $("p-ctkwh").textContent = v == null ? "" : (v / 10).toFixed(2) + " ct/kWh";
  $("p-res").textContent = z.res ? `${z.res}-min resolution` : "no data";

  drawChart(z);

  // 24 h stats
  const s = $("p-stats");
  if (z.price) {
    const last = z.price.slice(Math.max(0, state.tIdx - 95), state.tIdx + 1)
      .filter((x) => x != null);
    if (last.length) {
      const mn = Math.min(...last), mx = Math.max(...last);
      const av = last.reduce((a, b) => a + b, 0) / last.length;
      s.innerHTML = ["min", "avg", "max"].map((k, i) =>
        `<div class="stat"><div class="v">${[mn, av, mx][i].toFixed(1)}</div><div class="k">24h ${k}</div></div>`).join("");
    } else s.innerHTML = "";
  } else s.innerHTML = "";

  const c = state.data.countries[z.country];
  // carbon
  if (c && c.mix_ts) {
    const i = nearestIdx(c.mix_ts, t);
    const co2 = i >= 0 ? c.co2[i] : null;
    $("p-co2").innerHTML = co2 == null
      ? `<span class="co2-note">no data at this time</span>`
      : `<span class="co2-badge" style="background:${co2Color(co2)}22;color:${co2Color(co2)}">${co2} g</span>
         <span class="co2-note">CO₂eq/kWh · ${co2Word(co2)}<br>estimated from generation mix</span>`;
  } else $("p-co2").innerHTML = `<span class="co2-note">no generation data</span>`;

  // mix
  const mb = $("p-mixbar"), ml = $("p-mixlist");
  if (c && c.mix) {
    const i = nearestIdx(c.mix_ts, t);
    if (i >= 0) {
      const rows = Object.entries(c.mix)
        .map(([k, arr]) => [k, arr[i] || 0])
        .filter(([, x]) => x > 0)
        .sort((a, b) => b[1] - a[1]);
      const tot = rows.reduce((a, [, x]) => a + x, 0);
      if (tot > 0) {
        mb.innerHTML = rows.map(([k, x]) =>
          `<div style="width:${(x / tot * 100).toFixed(2)}%;background:${mixColor(k)}" title="${k}"></div>`).join("");
        const top = rows.slice(0, 7);
        const other = rows.slice(7).reduce((a, [, x]) => a + x, 0);
        if (other > 0) top.push(["Other sources", other]);
        ml.innerHTML = top.map(([k, x]) =>
          `<div class="row"><span class="dot" style="background:${mixColor(k)}"></span>${k}
           <span class="mw">${(x / tot * 100).toFixed(0)}% · ${(x * 1000).toFixed(1)} GW</span></div>`).join("");
      } else { mb.innerHTML = ""; ml.innerHTML = `<span class="co2-note">no generation data</span>`; }
    } else { mb.innerHTML = ""; ml.innerHTML = `<span class="co2-note">no data at this time</span>`; }
  } else { mb.innerHTML = ""; ml.innerHTML = `<span class="co2-note">no generation data</span>`; }

  // Germany drill-down: TSO control areas
  const deSec = $("p-de-sec"), deBox = $("p-de");
  if (name === "DE" && state.data.de_tso) {
    deSec.classList.remove("hidden");
    const tsos = TSO_ORDER.filter((k) => state.data.de_tso[k]);
    deBox.innerHTML = tsos.map((tso) => {
      const st = deStats(tso, t);
      const states = Object.values(state.data.de_states || {})
        .filter((s) => s.tso === tso).map((s) => s.name).join(", ");
      if (!st || st.gen <= 0) {
        return `<div class="dereg" data-tso="${tso}">
          <div class="dereg-head"><b>${tso}</b><span class="co2-note">no data</span></div>
          <div class="dereg-states">${states}</div></div>`;
      }
      const share = st.ren / st.gen;
      const bar = st.rows.map(([k, v]) =>
        `<div style="width:${(v / st.gen * 100).toFixed(2)}%;background:${deFuel(k)[1]}" title="${deFuel(k)[0]}"></div>`).join("");
      const top = st.rows.slice(0, 3).map(([k, v]) =>
        `${deFuel(k)[0]} ${(v / 1000).toFixed(1)}`).join(" · ");
      return `<div class="dereg" data-tso="${tso}">
        <div class="dereg-head"><b>${tso}</b>
          <span class="dereg-ren" style="color:${ramp(REN_STOPS, share)}">${Math.round(share * 100)}% renewable</span></div>
        <div class="dereg-states">${states}</div>
        <div class="dereg-stats">
          <span>${st.load != null ? (st.load / 1000).toFixed(1) : "–"} GW load</span>
          <span>${(st.gen / 1000).toFixed(1)} GW generation</span></div>
        <div class="mixbar dereg-mix">${bar}</div>
        <div class="dereg-top">${top}</div>
      </div>`;
    }).join("");
  } else deSec.classList.add("hidden");

  // flows
  const fl = $("p-flows");
  if (c && c.cbpf) {
    const i = nearestIdx(c.cbpf_ts, t);
    if (i >= 0) {
      const rows = Object.entries(c.cbpf)
        .map(([k, arr]) => [k, arr[i]])
        .filter(([, x]) => x != null && Math.abs(x) > 0.005)
        .sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]));
      fl.innerHTML = rows.length ? rows.map(([k, x]) => {
        const exp = x > 0;
        return `<div class="row"><span class="dir ${exp ? "exp" : "imp"}">${exp ? "→" : "←"}</span>
          <span class="name">${k}</span>
          <span class="gw ${exp ? "exp" : "imp"}">${Math.abs(x).toFixed(2)} GW ${exp ? "export" : "import"}</span></div>`;
      }).join("") : `<span class="co2-note">no recorded flows</span>`;
    } else fl.innerHTML = `<span class="co2-note">no data at this time</span>`;
  } else fl.innerHTML = `<span class="co2-note">no flow data</span>`;

  $("p-src").textContent =
    "Prices: energy-charts.info day-ahead (SMARD, CC BY 4.0) · Mix & flows: energy-charts.info · " +
    "DE regions: smard.de per control area (Bundesnetzagentur) · CO₂ estimated (IPCC AR5 factors)";
}

function co2Color(g) { return g < 150 ? "#4cc38a" : g < 350 ? "#f2d23c" : g < 600 ? "#f08a3c" : "#e5484d"; }
function co2Word(g) { return g < 150 ? "low" : g < 350 ? "moderate" : g < 600 ? "high" : "very high"; }

/* ---------- Germany drill-down (SMARD per TSO control area) ---------- */
const DE_FUEL = {
  lignite: ["Lignite", "#8a6a4f"], hard_coal: ["Hard coal", "#6b4f3f"],
  gas: ["Fossil gas", "#e05d4f"], nuclear: ["Nuclear", "#e5ae10"],
  wind_onshore: ["Wind onshore", "#66c2a5"], wind_offshore: ["Wind offshore", "#3288bd"],
  solar: ["Solar", "#ffc94d"], hydro: ["Hydro", "#4a80b4"],
  biomass: ["Biomass", "#3f9e4d"], pumped: ["Pumped storage", "#7a9cc6"],
  other: ["Other conv.", "#5a6675"], other_renew: ["Other renew.", "#4cc38a"],
};
const deFuel = (k) => DE_FUEL[k] || [k, "#5a6675"];
const DE_RENEWABLE = new Set(["wind_onshore", "wind_offshore", "solar",
  "hydro", "biomass", "other_renew"]);
const REN_STOPS = [[0, "#22303c"], [0.4, "#2a6e63"], [0.7, "#2aa881"], [1, "#4cc38a"]];
const TSO_ORDER = ["50Hertz", "Amprion", "TenneT", "TransnetBW"];

let deLayer = null, deGeoReq = null;

// stats for one control area at time t (unix s); values in MW.
// SMARD week files end with trailing nulls that lag differently per fuel,
// so scan back a few quarter-hours when the nearest slot is empty.
function deStats(tso, t) {
  const r = state.data.de_tso && state.data.de_tso[tso];
  if (!r || !r.ts) return null;
  let i = nearestIdx(r.ts, t);
  if (i < 0) return null;
  let gen = 0, ren = 0, back = 0;
  for (; back <= 8 && i - back >= 0; back++) {
    gen = ren = 0;
    for (const k in r.mix) {
      const v = r.mix[k][i - back] || 0;
      gen += v;
      if (DE_RENEWABLE.has(k)) ren += v;
    }
    if (gen > 0) break;
  }
  if (gen <= 0) return { gen: 0, ren: 0, rows: [], load: null };
  i -= back;
  const rows = [];
  for (const [k, arr] of Object.entries(r.mix)) {
    const v = arr[i] || 0;
    if (v > 0) rows.push([k, v]);
  }
  rows.sort((a, b) => b[1] - a[1]);
  let load = r.load ? r.load[i] : null;
  if (load == null && r.load) {
    for (let j = i - 1; j >= Math.max(0, i - 8); j--) {
      if (r.load[j] != null) { load = r.load[j]; break; }
    }
  }
  return { gen, ren, rows, load };
}

function deStyleFor(f) {
  const st = deStats(f.properties.tso, state.data.timeline[state.tIdx]);
  const share = st && st.gen > 0 ? st.ren / st.gen : null;
  return {
    fillColor: share == null ? "#232b35" : ramp(REN_STOPS, share),
    fillOpacity: share == null ? 0.45 : 0.78,
    color: "rgba(255,255,255,0.45)",
    weight: 1,
  };
}

function ensureDeLayer() {
  if (deLayer) return Promise.resolve(deLayer);
  if (!deGeoReq) deGeoReq = fetch(DE_GEO_URL).then((r) => {
    if (!r.ok) throw new Error("de geo " + r.status);
    return r.json();
  });
  return deGeoReq.then((geo) => {
    if (deLayer) return deLayer;
    deLayer = L.geoJSON(geo, {
      style: deStyleFor,
      onEachFeature: (f, layer) => {
        layer.on({
          mouseover: (e) => {
            layer.setStyle({ weight: 2, color: "rgba(255,255,255,0.9)" });
            layer.bringToFront();
            showDeTip(e.originalEvent, f.properties);
          },
          mousemove: (e) => showDeTip(e.originalEvent, f.properties),
          mouseout: () => {
            deLayer.resetStyle(layer);
            $("tooltip").classList.add("hidden");
          },
          click: (e) => {
            L.DomEvent.stopPropagation(e);
            selectZone("DE");
            flashTso(f.properties.tso);
          },
        });
      },
    });
    return deLayer;
  });
}

function showDeTip(ev, p) {
  const st = deStats(p.tso, state.data.timeline[state.tIdx]);
  const meta = (state.data.de_states || {})[p.zone] || {};
  const share = st && st.gen > 0 ? st.ren / st.gen : null;
  const estLoad = st && st.load != null && meta.share
    ? (st.load * meta.share / 1000).toFixed(1) + " GW"
    : "–";
  $("tooltip").innerHTML =
    `<b>${p.name}</b> · ${p.tso}<br>` +
    (share == null ? "no SMARD data at this time"
      : `${Math.round(share * 100)}% renewable · ~${estLoad} load (est.)`);
  const tip = $("tooltip");
  tip.style.left = ev.clientX + "px";
  tip.style.top = ev.clientY + "px";
  tip.classList.remove("hidden");
}

function showDeOverlay() {
  if (!state.data.de_tso || !Object.keys(state.data.de_tso).length) return;
  ensureDeLayer().then((l) => {
    if (state.selected === "DE" && map && !map.hasLayer(l)) l.addTo(map);
  }).catch((e) => console.error(e));
}
function hideDeOverlay() {
  if (deLayer && map && map.hasLayer(deLayer)) map.removeLayer(deLayer);
}
function restyleDeStates() {
  if (deLayer && map && map.hasLayer(deLayer))
    deLayer.eachLayer((l) => l.setStyle(deStyleFor(l.feature)));
}
function flashTso(tso) {
  const el = document.querySelector(`.dereg[data-tso="${tso}"]`);
  if (!el) return;
  el.classList.remove("flash"); void el.offsetWidth;
  el.classList.add("flash");
  el.scrollIntoView({ block: "nearest", behavior: "smooth" });
}

/* ---------- price chart ---------- */
function drawChart(z) {
  const cv = $("chart"), ctx = cv.getContext("2d");
  const W = cv.width, H = cv.height;
  ctx.clearRect(0, 0, W, H);
  if (!z.price) { return; }
  const vals = z.price.filter((x) => x != null);
  if (!vals.length) return;
  let mn = Math.min(...vals, 0), mx = Math.max(...vals, 0);
  const pad = (mx - mn) * 0.08 || 1; mn -= pad; mx += pad;
  const n = z.price.length;
  const X = (i) => i / (n - 1) * (W - 8) + 4;
  const Y = (v) => H - 12 - (v - mn) / (mx - mn) * (H - 28);

  // zero line
  if (mn < 0 && mx > 0) {
    ctx.strokeStyle = "rgba(255,255,255,0.18)";
    ctx.setLineDash([3, 4]);
    ctx.beginPath(); ctx.moveTo(0, Y(0)); ctx.lineTo(W, Y(0)); ctx.stroke();
    ctx.setLineDash([]);
  }
  // fill + line
  ctx.beginPath();
  let started = false;
  const pts = [];
  for (let i = 0; i < n; i++) {
    const v = z.price[i];
    if (v == null) { started = false; continue; }
    pts.push([i, v]);
    const x = X(i), y = Y(v);
    started ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    started = true;
  }
  ctx.strokeStyle = "#6dd3a7"; ctx.lineWidth = 1.6; ctx.stroke();
  ctx.lineTo(X(pts[pts.length - 1][0]), H - 12);
  ctx.lineTo(X(pts[0][0]), H - 12);
  ctx.closePath();
  ctx.fillStyle = "rgba(76,195,138,0.12)"; ctx.fill();

  // cursor
  const cx = X(state.tIdx);
  ctx.strokeStyle = "rgba(255,255,255,0.7)"; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(cx, 4); ctx.lineTo(cx, H - 12); ctx.stroke();
  const cur = z.price[state.tIdx];
  if (cur != null) {
    ctx.fillStyle = "#fff";
    ctx.beginPath(); ctx.arc(cx, Y(cur), 3, 0, 7); ctx.fill();
  }
  // min/max labels
  ctx.fillStyle = "#8b98a8"; ctx.font = "10px sans-serif";
  ctx.fillText(mx.toFixed(0), 6, 12);
  ctx.fillText(mn.toFixed(0), 6, H - 4);
  const tl = state.data.timeline;
  ctx.textAlign = "right";
  ctx.fillText(fmtD.format(new Date(tl[0] * 1000)), W - 6, 12);
  ctx.fillText(fmtD.format(new Date(tl[n - 1] * 1000)), W - 6, H - 4);
  ctx.textAlign = "left";

  cv.onclick = (e) => {
    const r = cv.getBoundingClientRect();
    const i = Math.round((e.clientX - r.left) / r.width * (n - 1));
    setTime(Math.max(0, Math.min(n - 1, i)));
  };
}

/* ---------- time controls ---------- */
function setTime(i) {
  state.tIdx = i;
  $("slider").value = i;
  restyle();
}
function updateTimeUI() {
  const tl = state.data.timeline, t = tl[state.tIdx];
  $("t-label").textContent = fmtDT.format(new Date(t * 1000));
  $("t-range").textContent =
    `${fmtD.format(new Date(tl[0] * 1000))} – ${fmtD.format(new Date(tl[tl.length - 1] * 1000))}`;
}
let timer = null;
function togglePlay() {
  state.playing = !state.playing;
  $("play").textContent = state.playing ? "❚❚" : "▶";
  if (state.playing) {
    timer = setInterval(() => {
      setTime((state.tIdx + 1) % state.data.timeline.length);
    }, 140);
  } else clearInterval(timer);
}

/* ---------- boot ---------- */
async function boot() {
  try {
    const [data, geo] = await Promise.all([
      fetch(DATA_URL).then((r) => { if (!r.ok) throw new Error("data.json " + r.status); return r.json(); }),
      fetch(GEO_URL).then((r) => { if (!r.ok) throw new Error("geo " + r.status); return r.json(); }),
    ]);
    state.data = data;

    // price domain: robust percentiles across all zones & timesteps
    const all = [];
    for (const z of Object.values(data.zones))
      if (z.price) for (const v of z.price) if (v != null) all.push(v);
    all.sort((a, b) => a - b);
    if (all.length) {
      domainLo = Math.min(all[Math.floor(all.length * 0.01)], -10);
      domainHi = Math.max(all[Math.floor(all.length * 0.99)], 50);
    }

    state.tIdx = data.timeline.length - 1;
    const sl = $("slider");
    sl.max = data.timeline.length - 1;
    sl.value = state.tIdx;
    sl.addEventListener("input", () => setTime(+sl.value));
    $("play").addEventListener("click", togglePlay);
    $("panel-close").addEventListener("click", () => {
      $("panel").classList.add("hidden"); state.selected = null;
      hideDeOverlay();
    });
    map && map.on && map.on("click", (e) => {
      if (!e.originalEvent.target.closest || e.originalEvent.target === map.getContainer()) {
        $("panel").classList.add("hidden");
        state.selected = null;
        hideDeOverlay();
      }
    });

    initMap(geo);
    buildLegend();
    restyle();
    const hz = location.hash.slice(1).toUpperCase();
    if (hz in data.zones) selectZone(hz);
    const ageMin = Math.round((Date.now() / 1000 - data.generated_at) / 60);
    if (ageMin > 120) {
      const chip = $("live-chip");
      chip.textContent = `SNAPSHOT ${Math.round(ageMin / 60)}h AGO`;
      chip.classList.add("stale");
    }
  } catch (e) {
    const el = $("err");
    el.textContent = "Failed to load map data: " + e.message +
      " — run fetch_data.py and serve this folder over HTTP.";
    el.classList.remove("hidden");
    console.error(e);
  }
}
boot();
